-- Add the unnumbered French basic Energy print designs missing from catalogue search.
-- The 2017 design continued to be distributed in 2018; 2020 design likewise covers 2021 prints.
begin;
do $$
declare
  existing_sets integer;
  inserted_cards integer;
begin
  select count(*)::integer into existing_sets
  from public.card_sets where language = 'FR' and set_code in ('uen17','uen19','uen20','uen22');
  if existing_sets <> 0 then
    raise exception 'Expected no pre-existing unnumbered Energy sets; found %', existing_sets;
  end if;
end;
$$;

insert into public.card_sets (series_name, set_name, set_code, language, release_date, advertised_card_count, checklist_source_url, checklist_scope_note, is_public) values
  ('Soleil et Lune', 'Énergie de base sans numéro · 2017', 'uen17', 'FR', '2017-02-03', 9, 'https://www.pokepedia.fr/Cat%C3%A9gorie:Carte_%C3%89nergie_de_base', 'Énergies de base non numérotées, indexées par visuel/copyright. Le visuel 2017 a également été distribué en 2018.', true),
