insert into public.cards (card_set_id, collector_number, card_name, card_type, guide_category_label, guide_category_code, rarity_label, guide_order, image_url, image_source_url, source_url, element_types)
select s.id, ep.internal_number, 'Énergie ' || ep.energy_type || ' de base', 'Énergie', null, null, 'Commune', ep.guide_order, ep.image_url, ep.image_source_url, ep.source_url, '{}'::text[]
from energy_prints ep
join public.card_sets s on s.set_code = ep.set_code and s.language = 'FR';

insert into public.card_print_variants (card_id, variant_key, variant_label, finish_code, checklist_group, is_master_set_target)
select c.id, 'catalog_base', 'Carte', 'standard', 'main', true
from public.cards c
join public.card_sets s on s.id = c.card_set_id
where s.set_code in ('uen17','uen19','uen20','uen22') and s.language = 'FR';

do $$
declare
  verified_sets integer;
  verified_cards integer;
  verified_variants integer;
begin
  select count(*)::integer into verified_sets from public.card_sets where language='FR' and set_code in ('uen17','uen19','uen20','uen22') and is_public;
  select count(*)::integer into verified_cards from public.cards c join public.card_sets s on s.id=c.card_set_id where s.language='FR' and s.set_code in ('uen17','uen19','uen20','uen22');
  select count(*)::integer into verified_variants from public.card_print_variants v join public.cards c on c.id=v.card_id join public.card_sets s on s.id=c.card_set_id where s.language='FR' and s.set_code in ('uen17','uen19','uen20','uen22') and v.variant_key='catalog_base';
  if verified_sets <> 4 or verified_cards <> 35 or verified_variants <> 35 then
    raise exception 'Unnumbered Energy catalog verification failed: sets %, cards %, variants %', verified_sets, verified_cards, verified_variants;
  end if;
end;
$$;
commit;
